import sys; sys.path.insert(0,'/home/claude/scripts')
from facts_lib import save
N="تعليمات منح شهادة الدبلوم المهني في الطب والجراحة البيطرية / كلية الطب البيطري"
F=[]
def r(c,a,q1,q2,q3): F.append(("rule",[1],c,a,q1,q2,q3))
r("المادة 1 و2","تسمى هذه التعليمات «تعليمات منح شهادة الدبلوم المهني في الطب والجراحة البيطرية»، ويعمل بها ابتداءً من العام الجامعي 2000/2001، وتسري على الطلبة المنتظمين المسجلين للحصول على درجة الدبلوم المهني في الطب والجراحة البيطرية في الجامعة.","على من تسري تعليمات الدبلوم المهني في الطب والجراحة البيطرية ومن أي عام يعمل بها؟","ما اسم التعليمات وما العام الجامعي الذي بدأ العمل بها؟","على مين بتنطبق تعليمات الدبلوم المهني البيطري؟")
r("المادة 3 و4","يقر مجلس العمداء الخطة الدراسية المؤدية لشهادة الدبلوم المهني في الطب والجراحة البيطرية من مجلس كلية الطب البيطري. وتقدم طلبات الالتحاق إلى عمادة كلية الدراسات العليا حسب نموذج خاص، ولا يبت في أي طلب إلا إذا استوفى جميع الأوراق الثبوتية، ثم يحول إلى كلية الطب البيطري.","من يقر الخطة الدراسية للدبلوم المهني في الطب والجراحة البيطرية؟","كيف تقدم طلبات الالتحاق بالدبلوم المهني البيطري؟","وين بقدم طلب الدبلوم المهني البيطري؟")
r("المادة 5 (أ، ج)","يفوض رئيس الجامعة بقبول الطلبة الوافدين (غير الأردنيين) في برامج الدراسات العليا استثناء من شرط التقدير في البكالوريوس. ويكون قبول من لا يحقق شرط النجاح في التوفل مشروطاً باجتيازه امتحان التوفل قبل التخرج، ويستثنى من ذلك من يتقنون اللغة الفرنسية الحاصلين على المستوى الخامس في امتحان TCF المعادل للتوفل (Paper Based 500).","هل يقبل الطالب الوافد في الدبلوم المهني البيطري بتقدير أقل من جيد؟","من لا يحقق شرط التوفل، هل يقبل في الدبلوم المهني البيطري؟","شو الاستثناء لمن بتقن اللغة الفرنسية بشرط التوفل؟")
r("قرار مجلس التعليم العالي (التوفل)","وافق مجلس التعليم العالي على السماح لطلبة الماجستير الذين لم يحققوا النجاح مرتين على الأقل في امتحان التوفل بعلامة 500 أو ما يعادلها بدراسة مساقات في اللغة الإنجليزية والنجاح فيها بديلاً عنه: من حصل على 400–499 يدرس مساقاً واحداً مستوى (2)، ومن حصل على 399 فما دون يدرس مساقين مستوى (1) و(2). ويعقد امتحان موحد للمستوى (2) في مراكز اللغات (الأردنية، اليرموك، مؤتة، الهاشمية)، ولا يعتبر اجتياز المساقات من ضمن المدة القصوى لنيل الدرجة.","ما بديل امتحان التوفل لمن رسب فيه مرتين في الدبلوم المهني البيطري؟","هل تحسب مساقات اللغة الإنجليزية ضمن المدة القصوى لنيل الدرجة؟","علامتي بالتوفل 399، شو لازم أدرس؟")
r("المادة 6","يتم قبول الطالب في الدبلوم المهني في الطب والجراحة البيطرية بقرار من عميد كلية الدراسات العليا بناءً على توصية من مجلس كلية الطب البيطري، ويبلغ القرار إلى الطالب ومدير القبول والتسجيل والكلية المعنية.","من يقرر قبول الطالب في الدبلوم المهني البيطري؟","من يبلغ بقرار القبول في الدبلوم المهني البيطري؟","مين بقبلني بالدبلوم المهني البيطري؟")
r("المادة 7","الحد الأدنى للساعات المعتمدة المطلوبة لنيل درجة الدبلوم المهني في الطب والجراحة البيطرية 18 ساعة معتمدة، والحد الأدنى للمدة فصلان دراسيان، والحد الأعلى أربعة فصول دراسية منذ بداية انتظامه بالدراسة.","كم ساعة معتمدة مطلوبة للدبلوم المهني في الطب والجراحة البيطرية؟","ما الحد الأدنى والأعلى لمدة الدراسة في الدبلوم المهني البيطري؟","كم فصل بحد أقصى بقدر أخلص الدبلوم المهني البيطري؟")
r("المادة 8 (أ، ب)","يعتبر طالب الدبلوم المهني البيطري فاقداً لمقعده إذا انقطع عن الدراسة فصلاً دراسياً واحداً دون عذر يقبله عميد كليته بناءً على توصية لجنة الدراسات العليا في الكلية ويقدم العذر قبل بداية الفصل الذي يلي فصل الانقطاع. وإذا رغب بالانسحاب من البرنامج فعليه التقدم بطلب خطي على النموذج المعد إلى وحدة القبول والتسجيل فتثبت ملاحظة (منسحب من الجامعة) ويفقد مقعده، ويبلغ عميد الدراسات العليا وعميد الكلية.","متى يفقد طالب الدبلوم المهني البيطري مقعده؟","كيف ينسحب الطالب من برنامج الدبلوم المهني البيطري وماذا يثبت في سجله؟","شو بخلي مقعدي يطير بالدبلوم المهني البيطري؟")
r("المادة 8 (ج)","يجوز للطالب الذي فقد مقعده التقدم بطلب جديد للقبول، وفي حال قبوله يحتفظ بسجله الأكاديمي كاملاً ويكمل متطلبات التخرج وفق الخطة المعمول بها عند عودته، وتحسب مدة دراسته السابقة ضمن الحدين الأعلى والأدنى. وإذا اختلفت الخطة يحسم فصل دراسي واحد من الحد الأدنى لسنوات التخرج مقابل كل 9 ساعات معتمدة تحتسب للطالب.","ماذا يحدث لسجل الطالب إذا أعيد قبوله بعد فقدان المقعد في الدبلوم المهني البيطري؟","كم ساعة يحسم مقابلها فصل من الحد الأدنى إذا اختلفت الخطة؟","فقدت مقعدي وبدي أرجع، علاماتي بتضل؟")
r("المادة 9","يسمح للطالب الانسحاب من مساقات وإضافة مساقات جديدة خلال الأسبوع الأول من بداية الفصلين الأول والثاني وخلال الأيام الدراسية الثلاثة الأولى من الفصل الصيفي، ولا تثبت المساقات المنسحب منها في سجله. ويسمح بالانسحاب من مساق خلال اثني عشر أسبوعاً من بداية الفصل الأول والثاني وخلال الأسابيع الستة الأولى من الصيفي، فيثبت المساق بملاحظة (منسحب) ولا يدخل في النجاح والرسوب ومتطلبات التخرج، ولا يجوز أن يقل عدد الساعات المسجلة نتيجة الانسحاب عن الحد الأدنى للعبء إلا بقرار من عميد الكلية بتنسيب من المرشد.","متى يسمح بالإضافة والانسحاب من المساقات في الدبلوم المهني البيطري؟","خلال كم أسبوعاً يسمح بالانسحاب من مساق في الفصل الأول والثاني والصيفي؟","فات الأسبوع الأول، بقدر أنسحب من مادة؟")
r("المادة 10 (أ، ب)","تشترط المواظبة للطالب في جميع المساقات، ويسجل مدرس المساق الحضور والغياب على كشوفات خاصة ويسلمها إلى رئيس القسم في نهاية كل فصل وتحفظ إلى نهاية الفصل الذي يليه. ولا يسمح للطالب بالتغيب عن أكثر من 20% من مجموع الساعات المقررة لكل مساق.","كم نسبة الغياب المسموحة في كل مساق في الدبلوم المهني البيطري؟","ماذا يفعل مدرس المساق بكشوف الحضور والغياب في الدبلوم المهني البيطري؟","كم نسبة الغياب المسموحة بالدبلوم المهني البيطري؟")
r("المادة 10 (ج)","إذا غاب الطالب أكثر من 20% من الساعات المقررة دون عذر قهري أو مرضي يقبل به عميد كليته يحرم من التقدم لجميع الامتحانات اللاحقة في ذلك المساق ويوضع له الحد الأدنى لعلامة المساق وهو 35%، وتدخل النتيجة في حساب معدله ما لم يكن قد انسحب من المساق خلال المدة المنصوص عليها في المادة 9/ب.","ما العلامة التي توضع للطالب المحروم بسبب الغياب في الدبلوم المهني البيطري؟","هل أحرم من الامتحانات إذا غبت أكثر من 20% بدون عذر؟","غبت أكثر من 20% بمساق، شو بصير فيه؟")
r("المادة 10 (د، هـ)","إذا غاب الطالب أكثر من 20% بعذر قهري أو مرضي يقبله عميد كليته فلا يجوز أن يتجاوز غيابه بعذر مقبول 30%، وإلا فلمجلس كلية الطب البيطري اعتباره منسحباً ويبلغ عميد الدراسات العليا ووحدة القبول والتسجيل خطياً قبل آخر موعد لتسليم نتائج الامتحانات النهائية. ويشترط في العذر المرضي شهادة صادرة عن المركز الصحي في الجامعة أو العيادة المخصصة للطلبة أو معتمدة منهما أو مستشفى الملك المؤسس عبد الله الجامعي، تقدم لعميد الكلية خلال أسبوعين من تاريخ الانقطاع، وفي الحالات القاهرة الأخرى خلال أسبوعين من زوال أسباب الغياب.","ما أقصى نسبة غياب بعذر مقبول في الدبلوم المهني البيطري؟","خلال كم أسبوعاً تقدم الشهادة المرضية في الدبلوم المهني البيطري؟","من أين لازم تكون الشهادة المرضية؟")
r("المادة 11 (أ، ب)","تحسب العلامة النهائية لكل مساق طبقاً لحساب العلامة النهائية في تعليمات برنامج الماجستير، وهي مجموع علامات الامتحان النهائي وعلامات الأعمال الفصلية، وقد تكون الامتحانات بعضها أو كلها أعمالاً تطبيقية أو تقارير أو بحوثاً، ويحدد مجلس القسم المعني كيفية إجراء الامتحانات وتوزيع العلامات.","كيف تحسب العلامة النهائية للمساق في الدبلوم المهني البيطري؟","من يحدد كيفية إجراء الامتحانات وتوزيع العلامات في الدبلوم المهني البيطري؟","شو بتتكون علامة المساق بالدبلوم المهني البيطري؟")
r("المادة 11 (ج)","إذا لم يتم الطالب متطلبات مساق أو تغيب عن الامتحان النهائي بعذر قهري أو مرضي يقبل به عميد الكلية التي تطرح المساق تسجل له علامة «غير مكتمل»، وعليه إزالتها خلال أسبوعين من بدء الفصل اللاحق بما في ذلك الصيفي إذا كان مسجلاً فيه، وإلا تسجل له العلامة المستحقة من الأعمال الفصلية. وعند قبول العذر يعقد امتحان تعويضي بالتنسيق خطياً مع رئيس القسم مكافئاً بنوع الأسئلة ومستواها.","خلال كم أسبوعاً يجب إزالة (غير مكتمل) في الدبلوم المهني البيطري؟","كيف يكون الامتحان التعويضي في الدبلوم المهني البيطري؟","غبت عن النهائي بعذر، شو بصير بعلامتي؟")
r("المادة 12 (أ، د)","الحد الأدنى لعلامة النجاح في المساق في الدبلوم المهني البيطري هو 70% والحد الأدنى للعلامة النهائية هو 35%. وتعطى نتائج المواد الاستدراكية على أساس النجاح أو الرسوب والحد الأدنى لعلامة النجاح فيها 50%.","ما الحد الأدنى لعلامة النجاح في المساق في الدبلوم المهني البيطري؟","ما الحد الأدنى لعلامة النجاح في المواد الاستدراكية في الدبلوم المهني البيطري؟","كم علامة النجاح بالدبلوم المهني البيطري؟")
r("المادة 12 (ب، ج، هـ)","المعدل التراكمي هو معدل علامات جميع المساقات التي درسها الطالب نجاحاً أو رسوباً ضمن الخطة حتى تاريخ حسابه، وإذا حصل على (غير مكتمل) يحسب معدله عند اكتمال العلامات وبأثر رجعي من حيث المراقبة أو الفصل. والمعدل الفصلي هو معدل مساقات ذلك الفصل مع مراعاة حكم المواد الاستدراكية، وتحسب المعدلات لأقرب منزلة عشرية.","كيف يحسب المعدل التراكمي والفصلي في الدبلوم المهني البيطري؟","إلى كم منزلة عشرية تحسب المعدلات في الدبلوم المهني البيطري؟","هل تدخل المواد الاستدراكية في المعدل؟")
r("المادة 13","يوضع الطالب تحت المراقبة إذا نقص معدله التراكمي عن 75% في نهاية أي فصل دراسي، أو كان راسباً في مساقين في أي فصل أو في جميع الفصول لتاريخه. وعليه إزالة الأسباب في مدة أقصاها فصل دراسي واحد دون الصيفي هو الفصل الذي بعد فصل وضعه تحت المراقبة، على ألا يتجاوز ذلك الحد الأعلى لمدة الدراسة.","ما حالات وضع طالب الدبلوم المهني البيطري تحت المراقبة؟","كم فصلاً يمهل الطالب لإزالة الوضع تحت المراقبة في الدبلوم المهني البيطري؟","شو بنحطني تحت المراقبة بالدبلوم المهني البيطري؟")
r("المادة 14","لا يجوز لطالب الدبلوم المهني البيطري إعادة دراسة أي مساق حصل فيه على علامة 75% أو أكثر، ولا يجوز إعادة دراسة المساق الواحد أكثر من مرة واحدة، وتحسب العلامة الجديدة فقط في المعدل التراكمي ولأغراض التخرج.","هل يجوز إعادة مساق حصلت فيه على 75% في الدبلوم المهني البيطري؟","كم مرة يجوز إعادة المساق الواحد وأي علامة تحسب؟","بقدر أعيد مادة نجحت فيها بعلامة عالية؟")
r("المادة 15","يفصل الطالب من برنامج الدبلوم المهني البيطري إذا رسب في ثلاثة مساقات مختلفة خلال مدة دراسته، أو رسب في مساقين مختلفين في فصل واحد ونقص معدله التراكمي عن 75%، أو رسب في مساق إجباري مرتين، أو لم يتمكن من إزالة الوضع تحت المراقبة، أو لم يتم متطلبات الدبلوم ضمن الحد الأعلى لمدة الدراسة (أربعة فصول).","ما حالات الفصل من برنامج الدبلوم المهني البيطري؟","هل أفصل إذا رسبت في مساق إجباري مرتين؟","كم مساق براسب فيه بيفصلوني؟")
r("المادة 15 (ب)","تصدر جميع قرارات الفصل في الدبلوم المهني البيطري سواء من القسم أو الكلية أو الجامعة من قبل مجلس العمداء بناءً على تنسيب من مدير وحدة القبول والتسجيل، وتقوم الوحدة بإشعار الطالب خطياً على آخر عنوان له لدى الجامعة.","من يصدر قرار الفصل في الدبلوم المهني البيطري وكيف يبلغ الطالب؟","كيف يعرف الطالب بقرار فصله؟","مين بصدر قرار الفصل؟")
r("المادة 16","متطلبات منح درجة الدبلوم المهني البيطري: النجاح في جميع المساقات حسب الخطة المعتمدة، ومعدل تراكمي لا يقل عن 75%، وقضاء الحد الأدنى للمدة المطلوبة وعدم تجاوز الحد الأعلى، وأن يسجل الطالب تسجيلاً منتظماً في جميع الفصول الدراسية له في الجامعة.","ما متطلبات منح درجة الدبلوم المهني في الطب والجراحة البيطرية؟","ما الحد الأدنى للمعدل التراكمي للتخرج في الدبلوم المهني البيطري؟","شو لازم أحقق عشان أتخرج من الدبلوم المهني البيطري؟")
r("المادة 17 و18","يبت مجلس الدراسات العليا في الإشكالات التي تنشأ عن تطبيق هذه التعليمات. والرئيس وعميد كلية الدراسات العليا وعميد الكلية المعنية ومدير القبول والتسجيل مسؤولون عن تطبيقها.","من يبت في الإشكالات الناشئة عن تطبيق تعليمات الدبلوم المهني البيطري؟","من المسؤول عن تطبيق تعليمات الدبلوم المهني البيطري؟","مين بحل المشاكل بتطبيق التعليمات؟")
